using System.Text.Json;using NovaStore.Models;
namespace NovaStore.Services;public static class CartExtensions {const string Key="nova_cart";public static List<CartLine> GetCart(this ISession session)=>JsonSerializer.Deserialize<List<CartLine>>(session.GetString(Key)??"[]")??new();public static void SetCart(this ISession session,List<CartLine> cart)=>session.SetString(Key,JsonSerializer.Serialize(cart));public static List<CartDisplay> Details(this ISession session,StoreService store)=>session.GetCart().Select(x=>new CartDisplay{Product=store.Find(x.ProductId)!,Quantity=x.Quantity}).Where(x=>x.Product!=null).ToList();}
